create extension if not exists pgcrypto;
do $$ begin create type public.app_role as enum ('main_admin','co_admin','area_manager','branch_manager','co'); exception when duplicate_object then null; end $$;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text not null,role public.app_role not null default 'co',is_active boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.branches(id uuid primary key default gen_random_uuid(),branch_code text not null unique,branch_name text not null,area_name text,is_active boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.employees(id uuid primary key default gen_random_uuid(),employee_code text not null unique,full_name text not null,phone text,email text,branch_id uuid references public.branches(id),reports_to uuid references public.employees(id),designation text,is_active boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.profile_permissions(id uuid primary key default gen_random_uuid(),profile_id uuid not null references public.profiles(id) on delete cascade,module_key text not null,can_view boolean not null default false,can_create boolean not null default false,can_update boolean not null default false,can_delete boolean not null default false,unique(profile_id,module_key));
create table if not exists public.members(id uuid primary key default gen_random_uuid(),member_code text not null unique,full_name text not null,phone text,branch_id uuid references public.branches(id),assigned_employee uuid references public.employees(id),admission_date date not null default current_date,is_active boolean not null default true,created_by uuid references public.profiles(id),created_at timestamptz not null default now());
create table if not exists public.savings_transactions(id uuid primary key default gen_random_uuid(),member_id uuid not null references public.members(id),transaction_date date not null default current_date,transaction_type text not null check(transaction_type in ('deposit','withdrawal')),amount numeric(14,2) not null check(amount>0),reference_no text,notes text,created_by uuid references public.profiles(id),created_at timestamptz not null default now());
create table if not exists public.loan_accounts(id uuid primary key default gen_random_uuid(),loan_no text not null unique,member_id uuid not null references public.members(id),principal numeric(14,2) not null check(principal>0),interest_rate numeric(7,3) not null default 0,term_months integer not null check(term_months>0),disbursement_date date not null,status text not null default 'active' check(status in ('active','closed','written_off')),created_by uuid references public.profiles(id),created_at timestamptz not null default now());
create table if not exists public.loan_transactions(id uuid primary key default gen_random_uuid(),loan_id uuid not null references public.loan_accounts(id),transaction_date date not null default current_date,amount numeric(14,2) not null check(amount>0),principal_paid numeric(14,2) not null default 0,interest_paid numeric(14,2) not null default 0,reference_no text,created_by uuid references public.profiles(id),created_at timestamptz not null default now());
create table if not exists public.audit_logs(id bigint generated always as identity primary key,actor_id uuid references public.profiles(id),action text not null,table_name text not null,record_id text,details jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
-- RLS is enabled immediately. Role- and branch-scoped policies are required before exposing business data.
do $$ declare t text; begin foreach t in array array['profiles','branches','employees','profile_permissions','members','savings_transactions','loan_accounts','loan_transactions','audit_logs'] loop execute format('alter table public.%I enable row level security',t); end loop; end $$;
drop policy if exists profile_read_self on public.profiles;
create policy profile_read_self on public.profiles for select to authenticated using(id=auth.uid());
